CREATE TABLE users (
	id INTEGER NOT NULL, 
	net_id VARCHAR(32), 
	student_id VARCHAR(16), 
	email VARCHAR(254), 
	first_name VARCHAR(100), 
	last_name VARCHAR(100), 
	is_admin BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	last_login_at DATETIME, 
	CONSTRAINT pk_users PRIMARY KEY (id), 
	CONSTRAINT ck_users_has_identifier CHECK (net_id IS NOT NULL OR email IS NOT NULL OR student_id IS NOT NULL), 
	CONSTRAINT ck_users_net_id_lower CHECK (net_id IS NULL OR net_id = lower(net_id)), 
	CONSTRAINT ck_users_email_lower CHECK (email IS NULL OR email = lower(email)), 
	CONSTRAINT uq_users_net_id UNIQUE (net_id), 
	CONSTRAINT uq_users_student_id UNIQUE (student_id), 
	CONSTRAINT uq_users_email UNIQUE (email), 
	CONSTRAINT ck_users_is_admin CHECK (is_admin IN (0, 1))
);

CREATE TABLE courses (
	id INTEGER NOT NULL, 
	term VARCHAR(32) NOT NULL, 
	subject VARCHAR(16) NOT NULL, 
	catalog VARCHAR(16) NOT NULL, 
	section VARCHAR(16), 
	title VARCHAR(200) NOT NULL, 
	join_code VARCHAR(16), 
	points_participation FLOAT NOT NULL, 
	points_correct FLOAT NOT NULL, 
	created_by INTEGER, 
	created_at DATETIME NOT NULL, 
	archived_at DATETIME, 
	CONSTRAINT pk_courses PRIMARY KEY (id), 
	CONSTRAINT uq_courses_term_subject_catalog_section UNIQUE (term, subject, catalog, section), 
	CONSTRAINT ck_courses_points_nonneg CHECK (points_participation >= 0 AND points_correct >= 0), 
	CONSTRAINT uq_courses_join_code UNIQUE (join_code), 
	CONSTRAINT fk_courses_created_by_users FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL
);

CREATE TABLE media (
	id INTEGER NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	file_path VARCHAR(500) NOT NULL, 
	mime_type VARCHAR(100) NOT NULL, 
	size_bytes INTEGER, 
	uploaded_by INTEGER, 
	created_at DATETIME NOT NULL, 
	CONSTRAINT pk_media PRIMARY KEY (id), 
	CONSTRAINT ck_media_image_only CHECK (mime_type LIKE 'image/%'), 
	CONSTRAINT uq_media_sha256 UNIQUE (sha256), 
	CONSTRAINT fk_media_uploaded_by_users FOREIGN KEY(uploaded_by) REFERENCES users (id) ON DELETE SET NULL
);

CREATE TABLE course_instructors (
	course_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	role VARCHAR(16) NOT NULL, 
	added_at DATETIME NOT NULL, 
	CONSTRAINT pk_course_instructors PRIMARY KEY (course_id, user_id), 
	CONSTRAINT ck_course_instructors_role CHECK (role IN ('owner', 'instructor', 'ta')), 
	CONSTRAINT fk_course_instructors_course_id_courses FOREIGN KEY(course_id) REFERENCES courses (id) ON DELETE CASCADE, 
	CONSTRAINT fk_course_instructors_user_id_users FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE enrollments (
	course_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	section VARCHAR(16), 
	source VARCHAR(16) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	added_at DATETIME NOT NULL, 
	CONSTRAINT pk_enrollments PRIMARY KEY (course_id, user_id), 
	CONSTRAINT ck_enrollments_source CHECK (source IN ('import', 'manual', 'self')), 
	CONSTRAINT ck_enrollments_status CHECK (status IN ('active', 'dropped')), 
	CONSTRAINT fk_enrollments_course_id_courses FOREIGN KEY(course_id) REFERENCES courses (id) ON DELETE CASCADE, 
	CONSTRAINT fk_enrollments_user_id_users FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE question_banks (
	id INTEGER NOT NULL, 
