CREATE TABLE questions (
	id INTEGER NOT NULL, 
	bank_id INTEGER, 
	author_id INTEGER NOT NULL, 
	type VARCHAR(16) NOT NULL, 
	body_md TEXT NOT NULL, 
	body_media_id INTEGER, 
	explanation_md TEXT, 
	explanation_media_id INTEGER, 
	text_answer TEXT, 
	numeric_answer FLOAT, 
	numeric_tolerance FLOAT, 
	copied_from_id INTEGER, 
	is_locked BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	CONSTRAINT pk_questions PRIMARY KEY (id), 
	CONSTRAINT ck_questions_type CHECK (type IN ('mc_single', 'mc_multi', 'free_text', 'numeric')), 
	CONSTRAINT ck_questions_has_body CHECK (body_md <> '' OR body_media_id IS NOT NULL), 
	CONSTRAINT ck_questions_tolerance_nonneg CHECK (numeric_tolerance IS NULL OR numeric_tolerance >= 0), 
	CONSTRAINT ck_questions_numeric_fields_only_for_numeric CHECK (type = 'numeric' OR (numeric_answer IS NULL AND numeric_tolerance IS NULL)), 
	CONSTRAINT fk_questions_bank_id_question_banks FOREIGN KEY(bank_id) REFERENCES question_banks (id) ON DELETE SET NULL, 
	CONSTRAINT fk_questions_author_id_users FOREIGN KEY(author_id) REFERENCES users (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_questions_body_media_id_media FOREIGN KEY(body_media_id) REFERENCES media (id) ON DELETE SET NULL, 
	CONSTRAINT fk_questions_explanation_media_id_media FOREIGN KEY(explanation_media_id) REFERENCES media (id) ON DELETE SET NULL, 
	CONSTRAINT fk_questions_copied_from_id_questions FOREIGN KEY(copied_from_id) REFERENCES questions (id) ON DELETE SET NULL, 
	CONSTRAINT ck_questions_is_locked CHECK (is_locked IN (0, 1))
);

