	CONSTRAINT pk_question_options PRIMARY KEY (id), 
	CONSTRAINT uq_question_options_question_id_position UNIQUE (question_id, position), 
	CONSTRAINT ck_question_options_position_nonneg CHECK (position >= 0), 
	CONSTRAINT fk_question_options_question_id_questions FOREIGN KEY(question_id) REFERENCES questions (id) ON DELETE CASCADE, 
	CONSTRAINT fk_question_options_media_id_media FOREIGN KEY(media_id) REFERENCES media (id) ON DELETE SET NULL, 
