	CONSTRAINT pk_responses PRIMARY KEY (id), 
	CONSTRAINT uq_responses_poll_id_user_id UNIQUE (poll_id, user_id), 
	CONSTRAINT fk_responses_poll_id_polls FOREIGN KEY(poll_id) REFERENCES polls (id) ON DELETE CASCADE, 
	CONSTRAINT fk_responses_user_id_users FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	CONSTRAINT ck_responses_is_correct CHECK (is_correct IN (0, 1))
);

