	CONSTRAINT pk_response_choices PRIMARY KEY (response_id, option_id), 
	CONSTRAINT fk_response_choices_response_id_responses FOREIGN KEY(response_id) REFERENCES responses (id) ON DELETE CASCADE, 
	CONSTRAINT fk_response_choices_option_id_question_options FOREIGN KEY(option_id) REFERENCES question_options (id) ON DELETE CASCADE
);

